"""Staging adds only explicitly listed, verified app bundles to a pinned release."""
import hashlib,json,subprocess,sys,tempfile,unittest
from pathlib import Path
SCRIPT=Path(__file__).resolve().parents[1]/'active-system/scripts/stage-simplified-app-batch.py'
def digest(data):return hashlib.sha256(data).hexdigest()
class StageNewApps(unittest.TestCase):
 def test_explicit_new_app_and_pinned_desktop(self):
  with tempfile.TemporaryDirectory() as temp:
   root=Path(temp);name='a'*64;base=root/name;assets=base/'assets/desktop';assets.mkdir(parents=True);(base/'app.js').write_bytes(b'old-app');(base/'style.css').write_bytes(b'old-style');(base/'desktop-apps.js').write_bytes(b'old-routes');(assets/'apps.mjs').write_bytes(b'old-loader');(assets/'offline-worker.js').write_text('/* worker */\nconst RELEASE='+json.dumps({'id':name})+';\n');(assets/'cache-manifest.json').write_text(json.dumps({'id':name}));(assets/'apps.json').write_text(json.dumps({'version':'test','apps':[{'id':'old','bundleSHA256':'b'*64}]}));(assets/'apps/old'/('b'*64)).mkdir(parents=True);(assets/'apps/old'/('b'*64)/'old').write_bytes(b'old')
   batch=root/'batch';payload=b'new app';bundle='c'*64;app=batch/'apps/new'/bundle;app.mkdir(parents=True);(app/'index.mjs').write_bytes(payload);record={'id':'new','bundleSHA256':bundle,'files':{'index.mjs':{'bytes':len(payload),'sha256':digest(payload)}}};(batch/'apps.json').write_text(json.dumps({'apps':[record]}));routes=root/'routes.js';routes.write_bytes(b'new-routes');style=root/'style.css';style.write_bytes(b'new-style');out=root/'out'
   cmd=[sys.executable,str(SCRIPT),'--baseline',str(base),'--batch',str(batch),'--output',str(out),'--apps','new','--desktop-apps',str(routes),'--desktop-apps-base-sha256',digest(b'old-routes')]
   self.assertNotEqual(subprocess.run(cmd,capture_output=True).returncode,0);self.assertFalse(out.exists())
   bad=subprocess.run(cmd+['--new-apps','new','old'],capture_output=True);self.assertNotEqual(bad.returncode,0);self.assertFalse(out.exists())
   stale=cmd.copy();stale[-1]='0'*64;self.assertNotEqual(subprocess.run(stale+['--new-apps','new'],capture_output=True).returncode,0);self.assertFalse(out.exists())
   desktop=root/'desktop.js';desktop.write_bytes(b'new-app');desktop_args=['--desktop-app',str(desktop),'--desktop-base-sha256',digest(b'old-app')];self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--desktop-app',str(desktop)],capture_output=True).returncode,0);self.assertFalse(out.exists());self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--desktop-app',str(desktop),'--desktop-base-sha256','0'*64],capture_output=True).returncode,0);self.assertFalse(out.exists());loader=root/'loader.mjs';loader.write_bytes(b'new-loader');loader_args=['--catalog-loader',str(loader),'--catalog-loader-base-sha256',digest(b'old-loader')];self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--catalog-loader',str(loader)],capture_output=True).returncode,0);self.assertFalse(out.exists());self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--catalog-loader',str(loader),'--catalog-loader-base-sha256','0'*64],capture_output=True).returncode,0);self.assertFalse(out.exists());linked=root/'linked.mjs';linked.symlink_to(loader);self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--catalog-loader',str(linked),'--catalog-loader-base-sha256',digest(b'old-loader')],capture_output=True).returncode,0);self.assertFalse(out.exists());style_args=['--desktop-style',str(style),'--desktop-style-base-sha256',digest(b'old-style')];self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--desktop-style',str(style)],capture_output=True).returncode,0);self.assertFalse(out.exists());self.assertNotEqual(subprocess.run(cmd+['--new-apps','new','--desktop-style',str(style),'--desktop-style-base-sha256','0'*64],capture_output=True).returncode,0);self.assertFalse(out.exists());result=subprocess.run(cmd+['--new-apps','new']+style_args+loader_args+desktop_args,capture_output=True,text=True,check=True);release=json.loads(result.stdout)['release'];catalog=json.loads((out/'assets/desktop/apps.json').read_text());self.assertEqual([x['id'] for x in catalog['apps']],['old','new']);self.assertEqual((out/'desktop-apps.js').read_bytes(),b'new-routes');self.assertEqual((out/'assets/desktop/apps/new'/bundle/'index.mjs').read_bytes(),payload);self.assertEqual(json.loads((out/'assets/desktop/cache-manifest.json').read_text())['id'],release)
   self.assertEqual((base/'app.js').read_bytes(),b'old-app');self.assertEqual((out/'app.js').read_bytes(),b'new-app');self.assertEqual(json.loads((out/'assets/desktop/cache-manifest.json').read_text())['files']['app.js']['sha256'],digest(b'new-app'));self.assertEqual((assets/'apps.mjs').read_bytes(),b'old-loader');self.assertEqual((out/'assets/desktop/apps.mjs').read_bytes(),b'new-loader');self.assertEqual(json.loads((out/'assets/desktop/cache-manifest.json').read_text())['files']['assets/desktop/apps.mjs']['sha256'],digest(b'new-loader'));self.assertEqual((base/'desktop-apps.js').read_bytes(),b'old-routes');self.assertEqual((base/'style.css').read_bytes(),b'old-style');self.assertEqual((out/'style.css').read_bytes(),b'new-style');self.assertEqual(json.loads((out/'assets/desktop/cache-manifest.json').read_text())['files']['style.css']['sha256'],digest(b'new-style'))
 def test_twenty_four_verified_app_assets_and_loader(self):
  with tempfile.TemporaryDirectory() as temp:
   root=Path(temp);name='a'*64;base=root/name;assets=base/'assets/desktop';assets.mkdir(parents=True)
   (assets/'apps.mjs').write_bytes(b'old-loader');(assets/'offline-worker.js').write_text('/* worker */\nconst RELEASE='+json.dumps({'id':name})+';\n');(assets/'cache-manifest.json').write_text(json.dumps({'id':name}))
   (assets/'apps').mkdir();existing=[{'id':f'old-{i}','bundleSHA256':'b'*64} for i in range(47)];(assets/'apps.json').write_text(json.dumps({'version':'codi-public-apps/2','hostAPI':2,'apps':existing}))
   batch=root/'batch';records=[];names=[]
   for i in range(24):
    appid=f'game-{i}';names.append(appid);payload=f'bundle-{i}'.encode();folder=batch/'apps'/appid/('c'*64);folder.mkdir(parents=True);(folder/'index.mjs').write_bytes(payload)
    records.append({'id':appid,'bundleSHA256':'c'*64,'files':{'index.mjs':{'bytes':len(payload),'sha256':digest(payload)}}})
   (batch/'apps.json').write_text(json.dumps({'version':'codi-public-apps/2','hostAPI':2,'apps':records}));loader=root/'loader.mjs';loader.write_bytes(b'new-loader');out=root/'out'
   cmd=[sys.executable,str(SCRIPT),'--baseline',str(base),'--batch',str(batch),'--output',str(out),'--apps',*names,'--new-apps',*names,'--catalog-loader',str(loader),'--catalog-loader-base-sha256',digest(b'old-loader')]
   tampered=batch/'apps/game-23'/('c'*64)/'index.mjs';tampered.write_bytes(b'tampered');self.assertNotEqual(subprocess.run(cmd,capture_output=True).returncode,0);self.assertFalse(out.exists());tampered.write_bytes(b'bundle-23')
   subprocess.run(cmd,capture_output=True,text=True,check=True);catalog=json.loads((out/'assets/desktop/apps.json').read_text());self.assertEqual(len(catalog['apps']),71);self.assertEqual((out/'assets/desktop/apps/game-23'/('c'*64)/'index.mjs').read_bytes(),b'bundle-23');self.assertEqual((out/'assets/desktop/apps.mjs').read_bytes(),b'new-loader')
if __name__=='__main__':unittest.main()
